"""Build an ANONYMISED Payentry Punch Location export as a real BIFF8 `.xls`.

⚠️ **NO REAL EXPORT EVER ENTERS THE REPOSITORY.** Invented people, invented
times, no coordinates that belong to anybody.

⚠️ **A REAL `.xls`, WRITTEN WITH xlwt, NOT A STAND-IN.** The export is an OLE2
container with a BIFF8 workbook stream, and `parse_punch_location` opens it
through xlrd. A fixture that handed the parser a list of rows would leave the
only part of Phase 2 that touches a binary format untested.

⚠️ **AND THE LAYOUT IS CHRONOLOGICAL, WHICH IS THE WHOLE HAZARD.** Payentry
re-emits an `Employee Name:` header every time the employee changes between
consecutive punches, so one person's punches scatter across blocks. Measured
on the real week-44 file: 28 blocks for 17 people, `Bell, Edward` in seven of
them, his Oct 26 out-punch in a LATER block than his in-punch. This fixture
reproduces that interleaving exactly, because pairing within a block would
otherwise look correct.
"""
from __future__ import annotations

import io

HEADER = ("Date", "Punch", "Latitude", "Longitude", "Accuracy",
          "IP Address", "Punch Origin")

#: (department, employee, date, time, location-cell, origin)
#: The two "Alpha"/"Bravo" employees interleave, as the two real Bells do.
PUNCHES = [
    ("[103] Production", "Alpha, Ann",  "Oct 26, 2026", "6:00a", "kiosk punch", "Kiosk"),
    ("[103] Production", "Bravo, Ben",  "Oct 26, 2026", "6:47a", "kiosk punch", "Kiosk"),
    ("[103] Production", "Bravo, Ben",  "Oct 26, 2026", "3:41p", "kiosk punch", "Kiosk"),
    # ⚠️ Ann's Oct 26 OUT punch, in a later block than her IN punch.
    ("[103] Production", "Alpha, Ann",  "Oct 26, 2026", "3:43p", "kiosk punch", "Kiosk"),
    ("[103] Production", "Alpha, Ann",  "Oct 27, 2026", "6:45a", "kiosk punch", "Kiosk"),
    ("[103] Production", "Bravo, Ben",  "Oct 27, 2026", "6:45a", "kiosk punch", "Kiosk"),
    ("[103] Production", "Bravo, Ben",  "Oct 27, 2026", "3:18p", "kiosk punch", "Kiosk"),
    ("[103] Production", "Alpha, Ann",  "Oct 27, 2026", "3:43p", "kiosk punch", "Kiosk"),
    # ── a GPS punch: a real-looking coordinate that must NOT be stored ──
    ("[101] Delivery",   "Delta, Dee",  "Oct 28, 2026", "6:25a", "42.9500517461", ""),
    ("[101] Delivery",   "Delta, Dee",  "Oct 28, 2026", "3:35p", "kiosk punch", "Kiosk"),
    # ── two people leaving together, well before 15:30 ──
    ("[103] Production", "Alpha, Ann",  "Oct 29, 2026", "6:00a", "kiosk punch", "Kiosk"),
    ("[103] Production", "Echo, Eve",   "Oct 29, 2026", "6:28a", "kiosk punch", "Kiosk"),
    ("[103] Production", "Alpha, Ann",  "Oct 29, 2026", "2:06p", "kiosk punch", "Kiosk"),
    ("[103] Production", "Echo, Eve",   "Oct 29, 2026", "2:06p", "kiosk punch", "Kiosk"),
    # ── an ODD number of punches: a missed punch, left unpaired ──
    ("[103] Production", "Foxtrot, Fay", "Oct 30, 2026", "6:29a", "kiosk punch", "Kiosk"),
    # ── a department with NO shift rule: must yield no findings ──
    ("[107] Office",     "Golf, Gus",   "Oct 30, 2026", "5:00a", "kiosk punch", "Kiosk"),
    ("[107] Office",     "Golf, Gus",   "Oct 30, 2026", "1:00p", "kiosk punch", "Kiosk"),
    # ── SATURDAY. ⚠️ Two people in at 06:00 and out together at 10:53 and
    #    10:58 — early by the weekday rule on both counts, and a finding on
    #    NEITHER, because Saturday has no regular shift. Measured on the real
    #    week 44: exactly this shape, four people out from 10:53, and the
    #    detector called it a finding. The fixture had no Saturday at all, so
    #    the Saturday tests ran on hand-built objects and never went through
    #    the xls container.
    ("[103] Production", "Alpha, Ann",  "Oct 31, 2026", "6:00a", "kiosk punch", "Kiosk"),
    ("[103] Production", "Bravo, Ben",  "Oct 31, 2026", "6:00a", "kiosk punch", "Kiosk"),
    ("[103] Production", "Alpha, Ann",  "Oct 31, 2026", "10:53a", "kiosk punch", "Kiosk"),
    ("[103] Production", "Bravo, Ben",  "Oct 31, 2026", "10:58a", "kiosk punch", "Kiosk"),
]

EXPECTED_PUNCHES = len(PUNCHES)
EXPECTED_PEOPLE = {"Alpha, Ann", "Bravo, Ben", "Delta, Dee", "Echo, Eve",
                   "Foxtrot, Fay", "Golf, Gus"}
#: ⚠️ MEASURED, not counted by hand — I guessed 13 and it was 12 before the
#: Saturday rows were added. Ann heads three blocks and Ben two in the first
#: department, which is the interleaving this fixture exists to reproduce.
EXPECTED_BLOCKS = 16

#: The Saturday rows: two people, in together and out together, early by the
#: weekday rule and a finding on neither.
EXPECTED_SATURDAY_PEOPLE = {"Alpha, Ann", "Bravo, Ben"}
EXPECTED_WITH_LOCATION = 1


def build() -> bytes:
    import xlwt

    book = xlwt.Workbook()
    sheet = book.add_sheet("Punch Location Report")
    r = 0

    def row(*vals):
        nonlocal r
        for c, v in enumerate(vals):
            sheet.write(r, c, v)
        r += 1

    row("Punch Location Report")
    row("")
    row("")
    row("Generated By : Tester [Test Person]")
    row("Generated On : Mon 2026-Nov-02 14:11")
    row("Date Criteria: From 2026-10-25 to 2026-10-31")
    row("Selected Departments:")
    row("    [101] Delivery")
    row("    [103] Production")
    row("    [107] Office")
    row("")

    dept = name = None
    for d, who, when, at, loc, origin in PUNCHES:
        if d != dept:
            dept = d
            # ⚠️ The Sales-style cell carries a [Map] link label and a newline
            # in the real file; reproduced on one department so the stripper
            # is exercised.
            row(f"Department: {d}" + ("\r\n[Map]" if d == "[107] Office" else ""))
            name = None
        if who != name:
            name = who
            row(f"Employee Name: {who}")
            row(*HEADER)
        row(when, at, loc, "", "", "10.0.0.1", origin)

    buf = io.BytesIO()
    book.save(buf)
    return buf.getvalue()
